function num(v){ const n = Number(v); return Number.isFinite(n) ? n : null; }
const q = $json.query || {};
const xmin = num(q.xmin), ymin = num(q.ymin), xmax = num(q.xmax), ymax = num(q.ymax);
const srid = q.srid ? parseInt(q.srid,10) : 4326;
const limit = q.limit ? Math.min(Math.max(parseInt(q.limit,10)||100,1),1000) : 100;
const offset = q.offset ? Math.max(parseInt(q.offset,10)||0,0) : 0;
const sort = (q.sort||'id').toString(); // 'id' or '-id'
const includeTotal = (q.includeTotal||'false').toString().toLowerCase()==='true';
if (xmin===null || ymin===null || xmax===null || ymax===null || xmin>=xmax || ymin>=ymax){
  return [{ json: { status: 400, error: 'Invalid bbox parameters' } }];
}
return [{ json: { xmin, ymin, xmax, ymax, srid, limit, offset, sort, includeTotal } }];

const features = items.map((it) => ({ type: 'Feature', id: it.json.id, geometry: JSON.parse(it.json.geometry), properties: it.json.properties }));
const total = $items('Postgres - Total', 0, 0).length ? Number($items('Postgres - Total', 0, 0)[0].json.total||0) : undefined;
const body = { type: 'FeatureCollection', features, crs: 'EPSG:4326', bbox: [$json.xmin, $json.ymin, $json.xmax, $json.ymax] };
if ($json.includeTotal && total!==undefined) body.totalCount = total;
return [{ json: body }];
